import assert from "node:assert/strict";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {legacy2018AutumnKnowledgeFacts as facts,legacy2018AutumnCapacitySteps as steps} from "./legacy-2018-autumn-foundations-knowledge-review";
/** All choice assertions are manually fixed in the facts. No production import,
 * answer field or automatically captured output is used to infer their truth. */
export function legacy2018AutumnKnowledgeOracle(source:string,b:GeneratedBody,v:number[]){const n=Number(source.split("-").at(-1)),f=facts.find(f=>f.number===n);assert(f);assert.equal(v.length,3);assert(v.every(n=>n===0||n===1));const paragraphs=b.prompt.map(p=>{assert(p.type==="paragraph");return p.text;});assert.deepEqual(paragraphs,n===14?[f.stem,"〔キャパシティプランニングの作業項目〕",...steps]:[f.stem]);assert.equal(b.choices.length,4);const options=b.choices.map(bs=>{assert.equal(bs.length,1);assert(bs[0].type==="paragraph");return bs[0].text;}),wrong=[0,1,2,3].filter(i=>i!==f.correct),expected=f.original.map((text,i)=>i!==f.correct&&v[wrong.indexOf(i)]?f.changed[wrong.indexOf(i)]:text);assert.deepEqual(options,expected);assert.equal(new Set(options).size,4);const reviewed=new Map<string,boolean>([...f.original.map((s,i)=>[s,i===f.correct] as const),...f.changed.map(s=>[s,false] as const)]),truth=options.map(s=>{assert(reviewed.has(s));return reviewed.get(s)!;});if(n===14){const symbols="①②③④",orders=options.map(s=>s.split("、").map(c=>symbols.indexOf(c)+1));for(const order of orders)assert.deepEqual([...order].sort(),[1,2,3,4]);const dependencies=[[3,2],[4,2],[2,1]];assert.deepEqual(truth,orders.map(order=>dependencies.every(([before,after])=>order.indexOf(before)<order.indexOf(after))));}assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));for(const term of f.explanation)assert(b.explanation.includes(term),`${n}:${term}`);assert(!/原資料では[アイウエ]が|[アイウエ]が正答/.test(b.explanation));return truth;}
